import {SHOPS,DISTRICTS,COLORS,COMPLETE,INCOMPLETE,KEEP,newGame,groups,groupIncome,income,holdings,claimPlots,beginBuild,canPlace,placeShop,finishYear,nextYear,emptyOffer,evaluateOffer,trade,rankings,validSave} from './engine.mjs';
const $=s=>document.querySelector(s),KEY='vietnamtown-save-v1';
let state;try{const saved=JSON.parse(localStorage.getItem(KEY));state=validSave(saved)?saved:newGame();}catch{state=newGame();}
let view='play',selectedShop=null,selectedLot=null,chosen=[],partner=1,lastFocus=null,toastTimer=null;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>`${n.toLocaleString('en-US')} <span class="money-symbol">đ</span>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('This browser cannot save progress. Keep this tab open to finish your game.');}}
function changed(){save();render();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function modal(title,content,eyebrow='VIETNAM TOWN'){lastFocus=document.activeElement;$('#modal').innerHTML=`<div class="modal-header"><div><p class="eyebrow">${eyebrow}</p><h2>${title}</h2></div><button class="close" aria-label="Close dialog" data-action="close">×</button></div><div class="modal-body">${content}</div>`;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function closeModal(){$('#modal').close();lastFocus?.focus?.();}
function lotLabel(l){const owner=l.owner===null?'Unclaimed':state.players[l.owner].name;return `Plot ${l.id+1}, ${DISTRICTS[Math.floor(l.id/12)]}, ${owner}${l.shop===null?', empty':', '+SHOPS[l.shop].name}${state.pending.includes(l.id)?', offered to you':''}`;}
const SPRITES=['coffee','banhmi','pho','flowers','tailor','grocery'];
const LANDMARKS=['tan-dinh','ben-thanh','thao-dien','cho-lon','binh-thanh','phu-nhuan'];
const ZODIAC=[['Tỵ','Snake','snake'],['Ngọ','Horse','horse'],['Mùi','Goat','goat'],['Thân','Monkey','monkey'],['Dậu','Rooster','rooster'],['Tuất','Dog','dog']];
const TOKEN_COLORS=['#39a883','#eec353','#dc6f57','#7fb5cf'];
let freshLots=[],zoom=1,pan={x:0,y:0},fitScale=1,drag=null,suppressClick=false,soundOn=false,audioCtx=null;
try{soundOn=localStorage.getItem('vietnamtown-sound')==='on';}catch{}
function sprite(kind,name,cls='',extra=''){return `<img class="pixel ${cls}" src="/assets/${kind}/${name}.png" alt="" draggable="false" ${extra}>`;}
function token(player,cls=''){return sprite('materials','token-'+player,'owner-token '+cls);}
function board(){return DISTRICTS.map((name,b)=>`<section class="district district-${b}" aria-label="${name}"><div class="landmark" title="${['Tân Định church','Bến Thành market','Riverside villas','Chợ Lớn market gate','Bà Chiểu market','A leafy Phú Nhuận alley'][b]}">${sprite('landmarks',LANDMARKS[b])}</div><div class="district-sign"><span>${String(b+1).padStart(2,'0')}</span><strong>${name}</strong></div><div class="district-grid">${state.lots.slice(b*12,b*12+12).map(l=>{const offered=state.pending.includes(l.id),picked=chosen.includes(l.id),shop=l.shop===null?null:SHOPS[l.shop],valid=state.phase==='build'&&selectedShop!==null&&canPlace(state,0,l.id,selectedShop);return `<button data-lot="${l.id}" class="lot ${l.owner!==null?'owned':''} ${l.owner===0?'mine':''} ${offered?'offered':''} ${picked?'picked':''} ${selectedLot===l.id?'inspected':''} ${shop?'built':''} ${valid?'buildable':''} ${freshLots.includes(l.id)?'fresh':''}" aria-label="${lotLabel(l)}" aria-pressed="${picked||selectedLot===l.id}" style="--piece-delay:${Math.max(0,Math.min(12,freshLots.indexOf(l.id)))*40}ms"><span class="plot-number">${l.id+1}</span>${shop?sprite('shops',SPRITES[l.shop],'built-shop'):'<span class="plot-edge"></span>'}${l.owner!==null?token(l.owner):picked?token(0,'draft-token'):''}${valid?sprite('shops',SPRITES[selectedShop],'build-ghost'):''}</button>`;}).join('')}</div></section>`).join('');}
function calendar(){return `<section class="calendar" aria-label="Six-year zodiac calendar"><p class="calendar-title">THE SIX-YEAR JOURNEY</p><div class="year-wheel">${sprite('materials','calendar-wheel','wheel-art')}<div class="year-pointer" style="--angle:${(state.year-1)*60}deg"><span></span></div>${ZODIAC.map((z,i)=>{const a=i*Math.PI/3;return `<button class="year-node ${i+1===state.year?'current':''} ${i+1<state.year?'past':''}" style="left:${50+35*Math.sin(a)}%;top:${50-35*Math.cos(a)}%" data-action="year-info" data-year="${i+1}" aria-label="Year ${i+1}, ${z[1]}${state.year===i+1?', current year':''}"><span>${z[0]}</span><small>${i+1}</small></button>`;}).join('')}<div class="year-center"><small>NĂM</small><strong>${state.year}</strong><span>${ZODIAC[state.year-1][1]}</span></div></div><p class="calendar-foot">${6-state.year} more ${6-state.year===1?'year':'years'} to grow your fortune</p></section>`;}
function playerCard(){return `<div class="player-rail">${state.players.map((p,i)=>`<button class="player-pocket ${i===0?'your-pocket':''}" style="--player-color:${TOKEN_COLORS[i]}" data-action="${i===0?'businesses':'player-info'}" data-player="${i}" aria-label="${escape(p.name)}, ${p.cash} đ, ${income(state,i)} đ income per year"><span class="pocket-token">${token(i)}<b>${i===0?'YOU':p.name.toUpperCase()}</b></span><span class="wallet"><strong>${money(p.cash)}</strong><small>+${income(state,i)} đ / year</small></span><span class="pocket-plots">${holdings(state,i).length}<small>plots</small></span></button>`).join('')}</div>`;}
function phaseCard(){let title,body,action;switch(state.phase){case'receive':title='Claim your corner.';body=`Place your counters on ${state.draftCount} of the glowing plots. Nearby addresses make good neighbors.`;action=`<div class="counter-bowl"><button data-drag-token="0" class="counter-stack" aria-label="Drag a green ownership counter onto an offered plot">${[0,1,2,3].map((n)=>token(0,`stack-${n}`)).join('')}</button><div><strong>${chosen.length}<span> / ${state.draftCount}</span></strong><small>counters placed</small></div></div><div class="address-strip">${state.pending.map(id=>`<button data-lot="${id}" class="address-slip ${chosen.includes(id)?'selected':''}" aria-pressed="${chosen.includes(id)}">${id+1}</button>`).join('')}</div><button class="primary wide" data-action="claim" ${chosen.length!==state.draftCount?'disabled':''}>Keep these addresses</button>`;break;case'trade':title='Shake on a good deal.';body='Swap addresses, shop pieces, and cash. Try offering for a plot next to your own.';action='<button class="primary wide" data-action="trade">Make a deal</button><button class="secondary wide" data-action="build">Time to build →</button>';break;case'build':title='Bring the street to life.';body='Drag a shop from your rack onto your empty plot. You can also select a shop, then tap its address.';action=`<div class="income-preview"><span>Next payday</span><strong>${money(income(state,0))}</strong></div><button class="primary wide" data-action="collect">Finish building & collect</button><small class="phase-caption">${holdings(state,0).filter(l=>l.shop===null).length} empty plots · ${state.players[0].tiles.reduce((a,b)=>a+b,0)} pieces in your rack</small>`;break;case'income':title='The year paid off.';body=`Your neighborhood earned ${state.lastIncome[0]} đ. The next turn of the calendar brings new opportunities.`;action=`<button class="primary wide" data-action="next">Welcome year ${state.year+1} →</button><button class="text-button" data-action="income">Count the earnings</button>`;break;default:title='A town to be proud of.';body='Six years of neighbors, bargaining, and big ideas. Time to see whose fortune grew the most.';action='<button class="primary wide" data-action="results">Reveal the winner</button><button class="secondary wide" data-action="new">Another neighborhood?</button>';}
return `<section class="turn-scroll"><div class="scroll-pin"></div><div class="phase-steps">${['receive','trade','build'].map((p,i)=>`<span class="${state.phase===p?'on':''}"><b>${i+1}</b>${['Receive','Trade','Build'][i]}</span>`).join('')}</div><h2>${title}</h2><p>${body}</p>${action}</section>`;}
function hand(){return `<section class="tile-rack" aria-label="Your shop pieces"><div class="rack-label"><span>YOUR SHOPS</span><strong>${state.players[0].tiles.reduce((a,b)=>a+b,0)} pieces</strong><button data-action="businesses" title="Your businesses">Business ledger ↗</button></div><div class="shop-tray">${SHOPS.map((s,i)=>`<button class="shop-piece ${selectedShop===i?'active':''} ${state.players[0].tiles[i]===0?'depleted':''}" data-shop="${i}" data-drag-shop="${i}" aria-pressed="${selectedShop===i}" aria-label="${s.name}, ${state.players[0].tiles[i]} pieces, target size ${s.size}, complete income ${COMPLETE[s.size]} đ"><span class="piece-count">×${state.players[0].tiles[i]}</span>${sprite('shops',SPRITES[i])}<strong>${s.name}</strong><small><span class="target-pips">${Array.from({length:s.size},()=>'<i></i>').join('')}</span>${COMPLETE[s.size]} đ</small></button>`).join('')}</div><div class="rack-hint" aria-live="polite">${selectedShop!==null?`<strong>${SHOPS[selectedShop].name}</strong> · Connect ${SHOPS[selectedShop].size} shops for ${COMPLETE[SHOPS[selectedShop].size]} đ each year. ${state.phase==='build'?'Tap or drop onto your empty address.':'Trading closes when you start building.'}`:'A shared edge. The same shop. Your color. That’s a growing business.'}</div></section>`;}
function selection(){if(selectedLot===null)return '';const l=state.lots[selectedLot];return `<div class="plot-inspector"><span class="inspector-address">${l.id+1}</span><div><strong>${DISTRICTS[Math.floor(l.id/12)]}</strong><small>${l.owner===null?'Unclaimed address':`${l.owner===0?'Your address':escape(state.players[l.owner].name)+'’s address'} · ${l.shop===null?'Empty plot':SHOPS[l.shop].name}`}</small></div>${state.phase==='trade'&&l.owner!==null&&l.owner!==0?`<button class="primary" data-action="trade-lot" data-id="${l.id}">Offer a trade</button>`:''}<button class="close" data-action="deselect" aria-label="Close plot details">×</button></div>`;}
function streetScene(){return `<div class="map-terrain" aria-hidden="true"><div class="river"><span>SÔNG SÀI GÒN</span></div><div class="road road-top"><span>ĐƯỜNG LÊ VĂN DUYỆT</span></div><div class="road road-middle"><span>ĐƯỜNG NGUYỄN TRÃI</span></div><div class="road road-bottom"><span>ĐƯỜNG VÕ VĂN KIỆT</span></div><div class="road road-left"></div><div class="road road-v1"><span>ĐƯỜNG ĐỒNG KHỞI</span></div><div class="road road-v2"><span>ĐƯỜNG HAI BÀ TRƯNG</span></div>${[0,1,2,3].map(i=>`<div class="crosswalk crosswalk-${i}"></div>`).join('')}<div class="park park-top"></div><div class="park park-bottom"></div>${[0,1,2,3,4,5,6,7].map(i=>sprite('landmarks','tree',`map-tree tree-${i}`)).join('')}${sprite('landmarks','scooter','traffic traffic-a')}${sprite('landmarks','scooter','traffic traffic-b')}<div class="board-seal"><small>SAIGON</small><strong>VIỆT NAM</strong><span>72 ADDRESSES · 6 NEIGHBORHOODS</span></div><span class="compass">N<br>↑</span></div>`;}
function render(){document.body.classList.toggle('notebook-open',view==='research');if(view==='research'){renderResearch();return;}const oldViewport=$('.map-viewport');if(oldViewport)fitScale=Number(oldViewport.dataset.fit)||fitScale;$('#app').innerHTML=`${playerCard()}<div class="play-stage"><section class="board-area" aria-label="Neighborhood game board"><div class="board-frame"><div class="map-viewport" tabindex="0" aria-label="Game map. Drag the streets to pan; use plus and minus to zoom."><div class="game-world">${streetScene()}${board()}</div></div><div class="board-engraving"><span>VIETNAM TOWN</span><span>THE NEIGHBORHOOD IS YOURS</span></div></div><div class="map-controls"><button data-action="zoom-out" aria-label="Zoom out">−</button><button data-action="zoom-reset" class="zoom-label" aria-label="Fit map">${Math.round(zoom*100)}%</button><button data-action="zoom-in" aria-label="Zoom in">+</button><span>Drag the streets to explore</span></div>${selection()}</section><aside class="game-sidebar">${calendar()}${phaseCard()}<button class="journal-button" data-action="history">Neighborhood journal <span>↗</span></button></aside></div>${hand()}<footer class="game-footer"><span>YOU + 3 COMPUTER NEIGHBORS</span><span>Saved on this browser · Fictional game currency</span><span><button data-action="research">Artbook & sources</button> · <button data-action="history">Journal</button></span></footer>`;requestAnimationFrame(fitMap);updateSoundButton();}
function fitMap(){const vp=$('.map-viewport'),world=$('.game-world');if(!vp||!world)return;fitScale=Math.min(vp.clientWidth/1100,vp.clientHeight/730);vp.dataset.fit=fitScale;const sx=1100*fitScale*zoom,sy=730*fitScale*zoom;pan.x=Math.max(-Math.max(0,(sx-vp.clientWidth)/2),Math.min(Math.max(0,(sx-vp.clientWidth)/2),pan.x));pan.y=Math.max(-Math.max(0,(sy-vp.clientHeight)/2),Math.min(Math.max(0,(sy-vp.clientHeight)/2),pan.y));world.style.transform=`translate(calc(-50% + ${pan.x}px),calc(-50% + ${pan.y}px)) scale(${fitScale*zoom})`;$('.zoom-label').textContent=Math.round(zoom*100)+'%';}
function clickLot(id){if(state.phase==='receive'){if(!state.pending.includes(id)){selectedLot=id;render();return;}selectedLot=null;if(chosen.includes(id))chosen=chosen.filter(x=>x!==id);else if(chosen.length<state.draftCount){chosen.push(id);freshLots=[id];playSound('place');}else toast(`You can keep ${state.draftCount} addresses. Lift a counter first.`);render();scheduleFreshClear();return;}if(state.phase==='build'&&selectedShop!==null){if(canPlace(state,0,id,selectedShop)){buildPiece(id,selectedShop);return;}toast('That piece needs one of your empty plots.');}selectedLot=id;render();}
function buildPiece(id,shop){const before=income(state,0);placeShop(state,id,shop);selectedLot=null;freshLots=[id];playSound('build');if(!state.players[0].tiles[shop])selectedShop=null;changed();scheduleFreshClear();toast(`${SHOPS[shop].name} is open. +${income(state,0)-before} đ per year.`);return {id,shop,annualIncome:income(state,0)};}
function scheduleFreshClear(){setTimeout(()=>{freshLots=[];document.querySelectorAll('.fresh').forEach(el=>el.classList.remove('fresh'));},1800);}
function updateSoundButton(){const b=$('#sound-toggle');if(!b)return;b.classList.toggle('sound-on',soundOn);b.setAttribute('aria-label',soundOn?'Turn sound off':'Turn sound on');b.setAttribute('aria-pressed',String(soundOn));b.title=soundOn?'Sound on':'Sound off';}
function playSound(kind='place'){if(!soundOn)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const t=audioCtx.currentTime;const frequencies=kind==='income'?[523,659,784]:kind==='build'?[392,587]:[440];frequencies.forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(f,t+i*.075);g.gain.setValueAtTime(0,t+i*.075);g.gain.linearRampToValueAtTime(.07,t+i*.075+.01);g.gain.exponentialRampToValueAtTime(.001,t+i*.075+.16);o.connect(g);g.connect(audioCtx.destination);o.start(t+i*.075);o.stop(t+i*.075+.18);});}catch{}}
function celebration(kind){const fx=$('#effects');if(!fx)return;if(kind==='year'){fx.innerHTML=`<div class="year-announcement"><small>THE CALENDAR TURNS</small><strong>Year ${state.year}</strong><span>${ZODIAC[state.year-1][0]} · ${ZODIAC[state.year-1][1]}</span></div>`;}else{fx.innerHTML=state.players.map((p,i)=>`<div class="income-float" style="left:${15+i*23}%;--delay:${i*.1}s">+${state.lastIncome[i]||0} đ</div>`).join('');playSound('income');}setTimeout(()=>{fx.innerHTML='';},2300);}
function openTrade(prefillLot=null){if(state.phase!=='trade')return toast('Deals open after you claim your plots, and close when you start building.');if(prefillLot!==null)partner=state.lots[prefillLot].owner;const buildSide=(player,key,label)=>`<section class="trade-side"><h3>${label}</h3><label class="trade-item">Cash (đ)<input name="${key}-cash" type="number" min="0" max="${state.players[player].cash}" step="1" value="0" aria-label="${label}: cash"></label><p class="mini-label">SHOP TILES</p>${SHOPS.map((s,i)=>`<label class="trade-item">${sprite('shops',SPRITES[i],'trade-shop-icon')}${s.name} <span class="muted">(${state.players[player].tiles[i]})</span><input type="number" name="${key}-tile-${i}" min="0" max="${state.players[player].tiles[i]}" step="1" value="0" aria-label="${label}: ${s.name} tiles"></label>`).join('')}<p class="mini-label">PLOTS · SHOPS STAY ON THE PLOT</p><div class="trade-lots">${holdings(state,player).map(l=>`<label class="trade-lot" title="${lotLabel(l)}"><input type="checkbox" name="${key}-lot" value="${l.id}" ${key==='take'&&prefillLot===l.id?'checked':''}>${l.id+1}${l.shop!==null?' '+SHOPS[l.shop].code:''}</label>`).join('')||'<span class="muted">No plots yet</span>'}</div></section>`;modal('A good deal starts here.',`<form id="trade-form"><div class="trade-select"><label for="partner">Trade with</label><select id="partner" name="partner">${state.players.slice(1).map(p=>`<option value="${p.id}" ${p.id===partner?'selected':''}>${p.name} · ${p.cash} đ</option>`).join('')}</select><span class="muted small">Computer neighbor</span></div><div class="trade-columns">${buildSide(0,'give','You give')}${buildSide(partner,'take','You receive')}</div><div id="trade-feedback" class="trade-feedback" role="status">Add any combination of cash, tiles, and plots. ${state.players[partner].name} values plots beside their own businesses.</div><div class="modal-actions"><button type="button" class="secondary" data-action="close">Back to the street</button><button type="submit" class="primary">Propose deal ↗</button></div></form>`,'TRADE · YEAR '+state.year);}
function readOffer(){const data=new FormData($('#trade-form'));const side=key=>({cash:Number(data.get(key+'-cash')),tiles:SHOPS.map((_,i)=>Number(data.get(key+'-tile-'+i))),lots:data.getAll(key+'-lot').map(Number)});return {partner:Number(data.get('partner')),give:side('give'),take:side('take')};}
function rules(){modal('Build a street worth coming back to.',`<p>You and three computer neighbors have six years to grow a business community. The most cash after the sixth payday wins.</p><ol><li><strong>Receive.</strong> Choose from your offered addresses, then receive shop tiles. You keep ${KEEP.join(', ')} plots in years 1–6. Tiles: 5 in year one, then 4 each year.</li><li><strong>Trade.</strong> Make as many deals as you like. Exchange cash, empty plots, built plots, and unused shop tiles. Both sides must accept; our computer neighbors assess each proposal.</li><li><strong>Build.</strong> Place any number of tiles on your own empty plots for free. Drag a shop from your rack to your empty address, or select the shop and tap its plot. Placement is permanent. Unused tiles carry over.</li><li><strong>Collect.</strong> Every business pays every year, even one just opened. The game ends after year six’s income.</li></ol><h3>What counts as one business?</h3><p>Tiles of the same shop type and owner connect along shared edges inside one block. Diagonals and streets don’t connect. Match the shop’s target size to complete it.</p><table><thead><tr><th>Tiles</th><th>Incomplete income</th><th>Complete income</th></tr></thead><tbody>${[1,2,3,4,5,6].map(n=>`<tr><td>${n}</td><td>${n===6?'—':INCOMPLETE[n]+' đ'}</td><td>${n>=3?COMPLETE[n]+' đ':'—'}</td></tr>`).join('')}</tbody></table><p class="rules-note">Example: three connected Cà phê tiles earn 50 đ every year. Three connected Phở tiles earn 40 đ; add a fourth to earn 80 đ. Separate businesses are paid separately.</p><h3>Small but useful details</h3><ul><li>You start with 50 đ. All amounts are fictional đồng; these are game values.</li><li>No building costs, rent, interest, or end-game resale value. Tied cash is broken by most shop tiles on the board; an exact tie is shared.</li><li>A group larger than its target pays as complete target-sized sets plus an incomplete remainder. You can keep growing along the block.</li><li>Switching to Build closes trading for that year. Check your deals first.</li><li>Progress saves only in this browser. These are local computer opponents, not online players. Cash is visible in this adaptation.</li></ul><button class="primary wide" data-action="close">Back to the neighborhood</button>`,'HOW TO PLAY');}
function incomeModal(){modal(state.phase==='ended'?'The last payday.':'Another year in the books.',`<p>Every completed and incomplete business has paid its owner.</p>${state.players.map((p,i)=>`<div class="score-row">${token(i)}<span>${escape(p.name)}</span><strong>+${money(state.lastIncome[i]??0)}</strong><span class="muted">Total ${p.cash} đ</span></div>`).join('')}<div class="modal-actions"><button class="primary" data-action="${state.phase==='ended'?'results':'next'}">${state.phase==='ended'?'Final standings':'Begin year '+(state.year+1)} →</button></div>`,'INCOME · YEAR '+state.year);}
function results(){const ranked=rankings(state),top=ranked[0].cash,topTiles=state.lots.filter(l=>l.owner===ranked[0].id&&l.shop!==null).length,winners=ranked.filter(p=>p.cash===top&&state.lots.filter(l=>l.owner===p.id&&l.shop!==null).length===topTiles);modal(winners.length>1?'A shared place at the top.':ranked[0].id===0?'This neighborhood is yours.':`${escape(ranked[0].name)} built a thriving neighborhood.`,`<p>${winners.length>1?winners.map(p=>escape(p.name)).join(' and ')+' tied':ranked[0].id===0?'You finished first':escape(ranked[0].name)+' finished first'} with ${top} đ after six years.</p>${ranked.map((p,i)=>`<div class="score-row ${winners.some(w=>w.id===p.id)?'winner':''}"><span>${i+1}</span>${token(p.id)}<span>${escape(p.name)}</span><strong>${money(p.cash)}</strong></div>`).join('')}<p class="muted">You made ${state.trades} accepted deals. Your businesses earned ${income(state,0)} đ in their final year. Unused tiles and empty plots have no final value. Cash ties are broken by the number of placed shop tiles.</p><div class="modal-actions"><button class="secondary" data-action="close">Explore the finished town</button><button class="primary" data-action="new">Start a new neighborhood</button></div>`,'SIX YEARS · FINAL STANDINGS');}
function businesses(){const g=groups(state,0);modal('Your businesses.',g.length?`<table><thead><tr><th>Business</th><th>Plots</th><th>Size / target</th><th>Yearly income</th></tr></thead><tbody>${g.map(b=>`<tr><td>${SHOPS[b.shop].name}</td><td>${b.lots.map(x=>x+1).join(', ')}</td><td>${b.size} / ${SHOPS[b.shop].size}${b.size>=SHOPS[b.shop].size?' ✓':''}</td><td>${groupIncome(b.shop,b.size)} đ</td></tr>`).join('')}</tbody></table><strong>Total: ${income(state,0)} đ per year</strong>`:'<p>No shops open yet. During Build, choose a shop tile and place it on one of your empty plots.</p>','YOUR LITTLE EMPIRE');}
function renderResearch(){$('#app').innerHTML=`<article class="research"><p class="eyebrow">THE DESIGN NOTEBOOK</p><h1>From Chinatown to Vietnam Town.</h1><p class="research-intro">Keep the negotiation. Give it a neighborhood that feels like home. This prototype translates Chinatown’s business-building puzzle into an original, fictional map of Sài Gòn.</p><div class="info-chips"><span>6 years</span><span>72 addresses</span><span>6 Vietnamese businesses</span><span>You + 3 computer neighbors</span></div><div class="research-grid"><section class="research-card"><p class="eyebrow">01 · THE ORIGINAL</p><h2>The deal is the game.</h2><p>Karsten Hartwig’s <em>Chinatown</em> is a negotiation game for 3–5 players. Over six rounds, players receive building cards and business tiles, trade freely, place shops, and collect income. Cash at the end decides the winner; placed shop tiles break a tie. <a href="https://cdn.1j1ju.com/medias/46/fa/78-chinatown-rulebook.pdf" target="_blank" rel="noopener noreferrer">2014 rulebook ↗</a></p><p>The clever part is uneven value. An address that is forgettable to you might finish somebody else’s business. Random allocations create reasons to negotiate; the neighborhood grid makes those reasons visible.</p><p>Connected, same-owner shops form businesses. A business of its target size earns more, and earlier completion pays off repeatedly.</p></section><section class="research-card"><p class="eyebrow">02 · THE ADAPTATION</p><h2>A familiar kind of commerce.</h2><p>Vietnam Town is about neighborhood livelihoods: coffee houses, food shops, florists, tailors, and corner grocers. The vocabulary, storefront art, and place names carry the setting.</p><p>The six block names draw from places in Hồ Chí Minh City. Their arrangement and street names form a fictional game map. Keeping Chợ Lớn in the town acknowledges the city’s Chinese-Vietnamese commercial heritage.</p><p>Use the same strategic question throughout: <em>“What can we trade so both of our streets work better?”</em></p></section></div><h2>Translate the mechanics, not just the labels.</h2><table><thead><tr><th>Chinatown mechanic</th><th>Vietnam Town interpretation</th><th>What it gives the player</th></tr></thead><tbody><tr><td>Building ownership cards</td><td>Numbered shop addresses in six neighborhood blocks</td><td>A visible reason to negotiate for adjacent space</td></tr><tr><td>Business tiles</td><td>Cà phê, Bánh mì, Phở, Tiệm hoa, Tiệm may, Tạp hóa</td><td>Distinct trades with target sizes from 3 to 6</td></tr><tr><td>Open negotiation</td><td>A two-sided offer of cash, addresses, and shop tiles</td><td>Package deals, counteroffers, and mutual benefit</td></tr><tr><td>Connected shops</td><td>Rows of matching businesses along the same block</td><td>Planning that depends on where other players own space</td></tr><tr><td>Annual income</td><td>Year-end shop earnings in fictional đồng</td><td>A reason to build early and value remaining paydays</td></tr><tr><td>Richest player wins</td><td>Most cash after the sixth year</td><td>A clear ending without extra scoring systems</td></tr></tbody></table><div class="research-grid"><section class="research-card"><p class="eyebrow">03 · PLAYABLE NOW</p><h2>A complete local game.</h2><ul><li>One player and three computer opponents.</li><li>Six full years of address drafting, negotiation, building, and income.</li><li>Arbitrary packages of plots, tiles, and cash, with bot acceptance and cash counteroffers.</li><li>Permanent placement, edge adjacency, ownership changes, income calculation, and final standings.</li><li>Automatic progress saving in this browser, plus a game journal.</li></ul><p><strong>Deliberate changes:</strong> 72 plots instead of the original 85, six shop types instead of twelve, a larger tile supply, adjusted draws, sequential address choices, visible money, and scripted opponents. The original income curve and overflow scoring are retained in fictional đồng units. Bot negotiation is a first way to test the economy; it cannot reproduce human bargaining.</p></section><section class="research-card"><p class="eyebrow">04 · THE NEXT BUILD</p><h2>Bring friends to the table.</h2><ol><li><strong>Playtest the economy.</strong> Check completion rates, rejected deals, and whether all shop types remain useful.</li><li><strong>Add online rooms.</strong> Use authoritative shared game state, visible shop tiles and private cash, simultaneous offers, reconnects, and a ready check before building.</li><li><strong>Make the town come alive.</strong> Expand the original Aseprite set with people, seasonal variants, and more shop opening animations.</li><li><strong>Refine the local voice.</strong> Add Vietnamese/English language choice and review details with Vietnamese players.</li></ol><p>Keep the visual identity, wording, and map original. A close commercial adaptation would need a separate rights review.</p></section></div><section class="research-card"><p class="eyebrow">THE ASEPRITE ARTBOOK</p><h2>A town built one pixel at a time.</h2><p>The shops, landmarks, counters, ground tiles, and zodiac wheel are original pixel drawings created in Aseprite. Each building has named editable layers for its ground, architecture, fixtures, goods, and details.</p><div class="art-gallery">${SHOPS.map((shop,i)=>`<figure>${sprite('shops',SPRITES[i])}<figcaption>${shop.name}</figcaption></figure>`).join('')}</div><p>Look for phin filters and low stools at the café; a glass baguette cart at the bánh mì shop; a stockpot and soup bowls at the phở kitchen; flower buckets, a dress form and áo dài, and grocer’s sacks and crates.</p><p><a href="https://www.vietnam.travel/things-to-do/secret-art-vietnamese-coffee" target="_blank" rel="noopener noreferrer">Vietnam Tourism: street coffee</a> · <a href="https://vietnam.travel/node/125" target="_blank" rel="noopener noreferrer">The story of phở</a> · <a href="https://www.vietnam.travel/things-to-do/explore-old-quarter-your-way" target="_blank" rel="noopener noreferrer">Neighborhood storefront references</a></p><div class="art-gallery">${DISTRICTS.map((name,i)=>`<figure>${sprite('landmarks',LANDMARKS[i])}<figcaption>${name}</figcaption></figure>`).join('')}</div><p>The landmark silhouettes include Tân Định’s pink church, Bến Thành’s clock tower, a Chợ Lớn market gateway, and the Bà Chiểu market frontage. Thảo Điền and Phú Nhuận are interpretive river-villa and leafy-alley scenes. <a href="https://visithcmc.net/en/news/kham-pha-cho-ben-thanh-diem-den-khong-the-bo-qua-o-tp-ho-chi-minh" target="_blank" rel="noopener noreferrer">HCMC Tourism reference ↗</a></p><div class="art-downloads"><a href="/assets/vietnamtown-aseprite-source.zip" download>Download all layered Aseprite sources</a><a href="/assets/vietnamtown-sprites.zip" download>Download the PNG sprite set</a></div></section><div class="source-links"><a href="https://boardgamegeek.com/boardgame/47/chinatown" target="_blank" rel="noopener noreferrer">Chinatown on BoardGameGeek ↗</a><a href="https://cdn.1j1ju.com/medias/46/fa/78-chinatown-rulebook.pdf" target="_blank" rel="noopener noreferrer">Z-Man Games rulebook (2014, mirrored) ↗</a></div><p class="muted" style="font-size:12px;margin-top:16px">Independent research prototype inspired by Chinatown. No affiliation with its designer or publisher. Original artwork; fictional neighborhood layout. Research checked September 2026.</p><button class="primary" data-action="play">Back to your neighborhood →</button></article>`;}
function act(action,el){switch(action){
case 'close':closeModal();break;
case 'play':view='play';render();window.scrollTo({top:0});break;
case 'research':if($('#modal').open)closeModal();view='research';render();window.scrollTo({top:0});break;
case 'rules':rules();break;
case 'sound':soundOn=!soundOn;try{localStorage.setItem('vietnamtown-sound',soundOn?'on':'off');}catch{}updateSoundButton();playSound();break;
case 'zoom-in':zoom=Math.min(2.5,Math.round((zoom+.25)*100)/100);fitMap();break;
case 'zoom-out':zoom=Math.max(1,Math.round((zoom-.25)*100)/100);fitMap();break;
case 'zoom-reset':zoom=1;pan={x:0,y:0};fitMap();break;
case 'year-info':{const y=Number(el.dataset.year),z=ZODIAC[y-1];modal(`Year ${y} · ${z[0]}`,`<div class="zodiac-detail">${sprite('materials','zodiac-'+z[2])}<p>The year of the ${z[1].toLowerCase()}.</p></div><p>${y<state.year?'This year is already in your neighborhood’s story.':y===state.year?'You are playing this year now.':'This year is still ahead. Finish the current year to move the marker.'}</p><p>Keep up to <strong>${KEEP[y-1]} new addresses</strong> and receive <strong>${y===1?5:4} shop pieces</strong>. Every business earns income when the year closes.</p><p class="rules-note">This game follows six successive zodiac animals, starting with Tỵ. It is a game calendar, not today’s calendar.</p>`,'THE ZODIAC WHEEL');break;}
case 'player-info':{const p=state.players[Number(el.dataset.player)];modal(`${escape(p.name)}’s corner of town.`,`<div class="neighbor-summary">${token(p.id)}<strong>${money(p.cash)}</strong><span>${holdings(state,p.id).length} addresses · ${income(state,p.id)} đ / year</span></div><p>${['','Linh looks for room to grow next door.','Minh drives a harder bargain.','An is usually open to a fair exchange.'][p.id]}</p><div class="art-gallery neighbor-hand">${SHOPS.map((s,i)=>`<figure>${sprite('shops',SPRITES[i])}<figcaption>${s.name} ×${p.tiles[i]}</figcaption></figure>`).join('')}</div>${state.phase==='trade'?`<button class="primary wide" data-action="trade-player" data-player="${p.id}">Make ${escape(p.name)} an offer</button>`:'<p class="muted">Trading opens after the new addresses are claimed each year.</p>'}`,'YOUR NEIGHBOR');break;}
case 'trade-player':partner=Number(el.dataset.player);openTrade();break;
case 'claim':{freshLots=[...chosen];claimPlots(state,chosen);chosen=[];selectedLot=null;changed();scheduleFreshClear();playSound('build');toast('Your counters are down. Let the bargaining begin.');break;}
case 'trade':openTrade();break;
case 'trade-lot':openTrade(Number(el.dataset.id));break;
case 'build':modal('All deals done?','<p>Starting Build closes trading for this year. Drag shop pieces onto your addresses to open them, then collect the income.</p><div class="modal-actions"><button class="secondary" data-action="close">Keep bargaining</button><button class="primary" data-action="confirm-build">Open the shops →</button></div>','TIME TO BUILD');break;
case 'confirm-build':beginBuild(state);selectedLot=null;selectedShop=state.players[0].tiles.findIndex(n=>n>0);if(selectedShop<0)selectedShop=null;closeModal();changed();playSound();break;
case 'place':buildPiece(selectedLot,selectedShop);break;
case 'deselect':selectedLot=null;render();break;
case 'collect':{const possible=holdings(state,0).some(l=>SHOPS.some((_,s)=>canPlace(state,0,l.id,s)));if(possible)modal('Close up for the year?','<p>You still have pieces that fit on your empty addresses. Keep them in your rack for a future year, or open more shops now.</p><div class="modal-actions"><button class="secondary" data-action="close">Keep building</button><button class="primary" data-action="confirm-collect">Collect this year’s income</button></div>','THE YEAR’S LAST CALL');else act('confirm-collect');break;}
case 'confirm-collect':{const before=new Set(state.lots.filter(l=>l.shop!==null).map(l=>l.id));finishYear(state);freshLots=state.lots.filter(l=>l.shop!==null&&!before.has(l.id)).map(l=>l.id);selectedLot=null;selectedShop=null;closeModal();changed();scheduleFreshClear();celebration('income');const y=state.year;setTimeout(()=>{if(state.year===y&&['income','ended'].includes(state.phase))incomeModal();},800);break;}
case 'income':incomeModal();break;
case 'next':nextYear(state);chosen=[];selectedLot=null;selectedShop=null;closeModal();changed();celebration('year');playSound('income');break;
case 'results':results();break;
case 'businesses':businesses();break;
case 'history':modal('From the neighborhood journal.',`<ul class="history">${state.logs.map(l=>`<li>${escape(l)}</li>`).join('')}</ul>`,'YOUR GAME');break;
case 'new':modal('Start a new neighborhood?','<p>This replaces the game saved in this browser. Your current neighborhood will not be recoverable.</p><div class="modal-actions"><button class="secondary" data-action="close">Keep this game</button><button class="primary" data-action="confirm-new">A fresh beginning</button></div>','NEW GAME');break;
case 'confirm-new':state=newGame();selectedLot=null;selectedShop=null;chosen=[];freshLots=[];zoom=1;pan={x:0,y:0};view='play';closeModal();changed();celebration('year');break;
}}
function preserveControlFocus(el){if(document.activeElement!==document.body)return;for(const attr of ['data-lot','data-shop','data-action'])if(el.hasAttribute(attr)){document.querySelector(`[${attr}="${el.getAttribute(attr)}"]`)?.focus({preventScroll:true});break;}}
document.addEventListener('click',e=>{if(suppressClick){suppressClick=false;e.preventDefault();return;}const el=e.target.closest('[data-action],[data-lot],[data-shop]');if(!el)return;try{if(el.dataset.lot!==undefined)clickLot(Number(el.dataset.lot));else if(el.dataset.shop!==undefined){const shop=Number(el.dataset.shop);selectedShop=selectedShop===shop?null:shop;render();playSound();if(state.phase!=='build')toast('Keep this piece in mind. Shops open during Build.');else if(state.players[0].tiles[shop]===0)toast('Your rack has none of this shop. Trade for more next year.');}else act(el.dataset.action,el);preserveControlFocus(el);}catch(error){toast(error.message);}});
function clearDrop(){document.querySelectorAll('.drop-target').forEach(l=>l.classList.remove('drop-target'));}
function cancelDrag(){drag=null;$('#drag-piece').className='';$('#drag-piece').innerHTML='';document.body.classList.remove('dragging');clearDrop();}
document.addEventListener('pointerdown',e=>{if(e.button!==0||$('#modal').open)return;const shop=e.target.closest('[data-drag-shop]'),counter=e.target.closest('[data-drag-token]'),vp=e.target.closest('.map-viewport');let type=null,index=null;if(shop&&state.phase==='build'&&state.players[0].tiles[Number(shop.dataset.dragShop)]>0){type='shop';index=Number(shop.dataset.dragShop);}else if(counter&&state.phase==='receive'){type='counter';index=0;}else if(vp){type='pan';}if(!type)return;drag={type,index,el:shop||counter||vp,id:e.pointerId,x:e.clientX,y:e.clientY,px:pan.x,py:pan.y,active:false};});
document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.active&&Math.hypot(dx,dy)<6)return;if(!drag.active){drag.active=true;try{drag.el.setPointerCapture(e.pointerId);}catch{}document.body.classList.add('dragging');if(drag.type==='shop'){selectedShop=drag.index;document.querySelectorAll('.lot').forEach(l=>l.classList.toggle('buildable',canPlace(state,0,Number(l.dataset.lot),drag.index)));}if(drag.type!=='pan'){$('#drag-piece').innerHTML=drag.type==='shop'?sprite('shops',SPRITES[drag.index]):token(0);$('#drag-piece').className='show'+(drag.type==='counter'?' token-drag':'');}}if(e.cancelable)e.preventDefault();if(drag.type==='pan'){pan.x=drag.px+dx;pan.y=drag.py+dy;fitMap();return;}$('#drag-piece').style.left=e.clientX+'px';$('#drag-piece').style.top=e.clientY+'px';clearDrop();const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-lot]');if(target){const id=Number(target.dataset.lot),valid=drag.type==='counter'?state.pending.includes(id):canPlace(state,0,id,drag.index);if(valid)target.classList.add('drop-target');}},{passive:false});
document.addEventListener('pointerup',e=>{if(!drag||e.pointerId!==drag.id)return;const ended=drag;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-lot]');cancelDrag();if(!ended.active)return;suppressClick=true;setTimeout(()=>suppressClick=false,250);if(ended.type==='pan')return;try{if(!target){render();return;}const id=Number(target.dataset.lot);if(ended.type==='counter'){if(!state.pending.includes(id))toast('Place your counter on one of the glowing addresses.');else if(chosen.includes(id))toast('You already placed a counter here.');else clickLot(id);}else if(canPlace(state,0,id,ended.index))buildPiece(id,ended.index);else{toast('That shop needs one of your empty addresses.');render();}}catch(error){toast(error.message);render();}});
document.addEventListener('pointercancel',()=>{if(drag?.active){cancelDrag();render();}else cancelDrag();});
window.addEventListener('blur',()=>{if(drag){cancelDrag();render();}});
window.addEventListener('resize',fitMap);
document.addEventListener('keydown',e=>{if($('#modal').open)return;if(e.key==='Escape'){cancelDrag();selectedShop=null;selectedLot=null;render();}const vp=$('.map-viewport');if(e.target===vp){if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','0'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')pan.x+=45;if(e.key==='ArrowRight')pan.x-=45;if(e.key==='ArrowUp')pan.y+=45;if(e.key==='ArrowDown')pan.y-=45;if(e.key==='+')zoom=Math.min(2.5,zoom+.25);if(e.key==='-')zoom=Math.max(1,zoom-.25);if(e.key==='0'){zoom=1;pan={x:0,y:0};}fitMap();}}});
document.addEventListener('change',e=>{if(e.target.id==='partner'){partner=Number(e.target.value);openTrade();}});
document.addEventListener('submit',e=>{if(e.target.id!=='trade-form')return;e.preventDefault();try{const offer=readOffer(),result=trade(state,offer);if(result.accepted){closeModal();changed();playSound('income');toast(`Deal accepted. ${state.players[offer.partner].name} says, “Good doing business with you!”`);}else{$('#trade-feedback').innerHTML=`${state.players[offer.partner].name}: “We’re not quite there. Add <strong>${result.shortfall} đ</strong> to your offer, or change the package.”`;}}catch(error){$('#trade-feedback').textContent=error.message;}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
state.logs=state.logs.map(l=>l.replaceAll('million ₫','đ').replaceAll('M₫','đ'));
render();save();
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'get_neighborhood_state',description:'Read the local Vietnam Town game: phase, players, plots, shop tiles and offered addresses.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>JSON.parse(JSON.stringify(state))});register({name:'claim_neighborhood_plots',description:'Complete the Receive phase by claiming the required number of offered plots. Plot IDs are zero-based.',inputSchema:{type:'object',properties:{plotIds:{type:'array',items:{type:'integer'},uniqueItems:true}},required:['plotIds'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{claimPlots(state,input.plotIds);chosen=[];changed();return {phase:state.phase,ownedPlots:holdings(state,0).map(l=>l.id)};}});register({name:'start_neighborhood_build',description:'Close trading for this year and start the Build phase.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{beginBuild(state);changed();return {phase:state.phase};}});register({name:'place_neighborhood_shop',description:'Permanently place one shop tile on your empty plot during Build. Plot IDs and shop indices are zero-based.',inputSchema:{type:'object',properties:{plotId:{type:'integer'},shopIndex:{type:'integer'}},required:['plotId','shopIndex'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{return buildPiece(input.plotId,input.shopIndex);}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
